[{"order":1,"type":"heading","text":"Local Persistence in React Native: MMKV, AsyncStorage, SQLite, and WatermelonDB"},{"order":2,"type":"paragraph","text":"Choosing the right local persistence strategy is critical for building performant and reliable React Native applications. Different use cases require different storage mechanisms, ranging from simple key-value pairs to complex, relational, and reactive databases."},{"order":3,"type":"heading","text":"1. AsyncStorage: The Classic Key-Value Store"},{"order":4,"type":"paragraph","text":"AsyncStorage is an unencrypted, asynchronous, persistent, key-value storage system that is global to the app. It is best suited for small amounts of data like user preferences or authentication tokens."},{"order":5,"type":"code","text":"import AsyncStorage from '@react-native-async-storage/async-storage';

const storeData = async (value) => {
  try {
    await AsyncStorage.setItem('@storage_Key', value);
  } catch (e) {
    console.error('Failed to save data.');
  }
};

const getData = async () => {
  try {
    const value = await AsyncStorage.getItem('@storage_Key');
    if(value !== null) {
      return value;
    }
  } catch(e) {
    console.error('Failed to read data.');
  }
};"},{"order":6,"type":"heading","text":"2. MMKV: The Ultra-Fast Key-Value Alternative"},{"order":7,"type":"paragraph","text":"Tencent\'s MMKV is an efficient, small, mobile key-value storage framework that uses memory mapping (mmap) to sync keys and values. It is significantly faster than AsyncStorage and performs all operations synchronously."},{"order":8,"type":"code","text":"import { MMKV } from 'react-native-mmkv';

export const storage = new MMKV();

// Store data synchronously
storage.set('user.name', 'John Doe');
storage.set('user.age', 30);
storage.set('isLoggedIn', true);

// Retrieve data
const userName = storage.getString('user.name');
const age = storage.getNumber('user.age');"},{"order":9,"type":"heading","text":"3. SQLite: Relational Data Management"},{"order":10,"type":"paragraph","text":"When your application requires complex querying, relational integrity, and structured datasets, SQLite is the standard choice. Libraries like expo-sqlite provide robust access to a local SQL database."},{"order":11,"type":"code","text":"import * as SQLite from 'expo-sqlite';

const db = SQLite.openDatabase('mydb.db');

const createTable = () => {
  db.transaction(tx => {
    tx.executeSql(
      'CREATE TABLE IF NOT EXISTS items (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT);',
      [],
      () => console.log('Table created successfully'),
      (_, error) => { console.log(error); return false; }
    );
  });
};"},{"order":12,"type":"heading","text":"4. WatermelonDB: Reactive Database for Complex Apps"},{"order":13,"type":"paragraph","text":"WatermelonDB is a high-performance, reactive database built specifically for React Native and Expo. It is optimized for building complex offline-first applications with thousands of records without sacrificing UI responsiveness."},{"order":14,"type":"code","text":"import { Model } from '@nozbe/watermelondb';
import { field, text } from '@nozbe/watermelondb/decorators';

export default class Task extends Model {
  static table = 'tasks'

  @text('title') title;
  @field('is_completed') isCompleted;
}"},{"order":15,"type":"heading","text":"Summary: Which One Should You Choose?"},{"order":16,"type":"bullet_point","text":"AsyncStorage: Legacy projects or basic non-performance-critical key-value storage."},{"order":17,"type":"bullet_point","text":"MMKV: Modern greenfield apps requiring blistering fast, synchronous key-value storage."},{"order":18,"type":"bullet_point","text":"SQLite: Relational schemas, heavy querying, and local raw SQL execution."},{"order":19,"type":"bullet_point","text":"WatermelonDB: Large-scale offline-first apps needing reactive bindings and lazy loading."}]
